// A workflow is plain data: questions grouped into pages, computed values,
// and document templates. Everything that decides behaviour (show-if rules,
// computed values, template conditions) is a string in one expression
// language, so a workflow can be written by hand, edited in the builder, or
// generated by AI, and validated the same way in every case.

export type QuestionType =
  | "text"
  | "textarea"
  | "number"
  | "currency"
  | "date"
  | "yesno"
  | "choice"
  | "multichoice"
  | "list";

/** Field types allowed inside a repeating list item (no nested lists). */
export type FieldType = Exclude<QuestionType, "list">;

export interface Option {
  value: string;
  label: string;
}

export interface Field {
  /** Variable name, e.g. `name` → `child.name` inside a loop. */
  id: string;
  label: string;
  type: FieldType;
  options?: Option[];
  required?: boolean;
}

export interface Question {
  /** Variable name used in rules and templates, e.g. `client_type`. */
  id: string;
  label: string;
  type: QuestionType;
  help?: string;
  required?: boolean;
  options?: Option[];
  /** Expression; the question is asked only when this is true. */
  showIf?: string;
  /** Path into the case record, e.g. `case.client.name`, used as the starting answer. */
  prefill?: string;
  /** For `list` questions: the fields asked for each item. */
  fields?: Field[];
}

export interface Page {
  id: string;
  title: string;
  showIf?: string;
  questions: Question[];
}

export interface Computed {
  id: string;
  label?: string;
  expr: string;
}

export interface DocTemplate {
  id: string;
  name: string;
  /** Only generate this document when the expression is true. */
  showIf?: string;
  /** Template text: Markdown-lite with `{{ expr }}`, `{% if %}` and `{% for %}` tags. */
  body: string;
  /** An uploaded Word template; when present it is used instead of `body`. */
  docx?: { fileName: string; data: string };
}

export interface Workflow {
  id: string;
  name: string;
  description?: string;
  pages: Page[];
  computed: Computed[];
  documents: DocTemplate[];
}

export type Value = string | number | boolean | null | Value[] | { [key: string]: Value };

export type Answers = Record<string, Value>;
